src = open('playtest.mjs').read()

# nav: blind the bots (hp 0 player is invisible to vision) -> pure patrol,
# otherwise open maps lock every bot into strafe-in-place combat
old = """    const sp = GAME.game.map.PLAYER_SPAWN;
    GAME.test.pose(sp.x, 0, sp.z, 0, 0);
    const a = GAME.test.botInfo().map(b => [...b.pos]);"""
new = """    const sp = GAME.game.map.PLAYER_SPAWN;
    GAME.test.pose(sp.x, 0, sp.z, 0, 0);
    GAME.game.player.hp = 0; // invisible to bot vision: measure pure patrol
    const a = GAME.test.botInfo().map(b => [...b.pos]);"""
assert old in src
src = src.replace(old, new)

# engage: count damage events instead of polling hp (a fast kill + round
# reset can hide the hp dip from a poller)
old = """const engaged = await page.evaluate(async () => {
  GAME.test.start('vector');
  GAME.test.skipBuy();
  await new Promise(r => setTimeout(r, 200));
  const t0 = GAME.game.time;
  const w0 = Date.now();
  while (GAME.game.time - t0 < 10 && Date.now() - w0 < 90000) { // 10 sim-seconds
    const b = GAME.test.botInfo()[0];
    GAME.test.pose(b.pos[0] + 2.5, 0, b.pos[2] + 1.5, 0, 0); // <4u: in vision radius
    await new Promise(r => setTimeout(r, 200));
    if (GAME.test.state().hp < 100) {
      return { hp: GAME.test.state().hp, simT: +(GAME.game.time - t0).toFixed(1) };
    }
  }
  return { hp: 100, simT: 10 };
});
check('bot AI spots and engages exposed player', engaged.hp < 100, `hp ${engaged.hp} after ${engaged.simT} sim-s`);"""
new = """const engaged = await page.evaluate(async () => {
  GAME.test.start('vector');
  GAME.test.skipBuy();
  let hits = 0;
  const orig = GAME.game.events.onPlayerDamage;
  GAME.game.events.onPlayerDamage = (...a) => { hits++; orig(...a); };
  await new Promise(r => setTimeout(r, 200));
  const t0 = GAME.game.time;
  const w0 = Date.now();
  while (GAME.game.time - t0 < 12 && Date.now() - w0 < 90000 && hits === 0) {
    const b = GAME.test.botInfo()[0];
    GAME.test.pose(b.pos[0] + 2.5, 0, b.pos[2] + 1.5, 0, 0); // <4u: in vision radius
    await new Promise(r => setTimeout(r, 150));
  }
  GAME.game.events.onPlayerDamage = orig;
  return { hits, simT: +(GAME.game.time - t0).toFixed(1) };
});
check('bot AI spots and engages exposed player', engaged.hits > 0, `${engaged.hits} hits taken in ${engaged.simT} sim-s`);"""
assert old in src
src = src.replace(old, new)

# bloom check: own resolution (a leftover 0.4 scale makes the diff invisible)
old = """// bloom visibly changes the frame
await page.evaluate(() => { GAME.test.start('vector'); GAME.test.skipBuy(); GAME.test.pose(0, 0, 10, 0, -0.05); });"""
