await page.evaluate(() => {
  GAME.test.setSetting('graphics.resolutionScale', 0.75);
  GAME.test.start('vector'); GAME.test.skipBuy(); GAME.test.pose(0, 0, 10, 0, -0.05);
});"""
assert old in src
src = src.replace(old, new)
open('playtest.mjs', 'w').write(src)
